// The Thesis tab has a MERGED two-row header, so column NAMES are unusable:
// row 1 is 'Firm name | Contact person name | email | [merged] Updated thesis ...' and the real
// labels (Sector / Stage / Cheque / Geography / ARR) live in row 2, which a reader treats as data.
// So: locate the row containing 'Sector' and map columns BY POSITION from it. Abort if the shape
// changes, rather than silently writing the wrong field onto an investor.
const ALIAS = {
  'piperserica': 'PiperSireca', 'ricebergvc': 'Riceberg Ventures', 'vertex': 'Vertex Ventures',
  'sianacapital': 'Siana Capital', '247vc': '247 VC Tech Fund', 'swishinvc': 'Swishin Ventures',
  'atomiccapital': 'Atomic Capital', 'cedarhillcapital': 'CedarHill Capital',
  'rainmatterzerodha': 'Rainmatter by Zerodha', 'zerencapital': 'Zeren Capital',
  'lorealventurecapital': "L'Oreal Venture Capital"
};
function s(v) { return String(v == null ? '' : v).trim(); }
function norm(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function skip(v) { const t = s(v).toLowerCase(); return t === '' || t === 'same as previous'; }

// NOTE: the Sheets node injects its own 'row_number' key into every row. Taking Object.values
// blindly makes row_number column 0 and shifts every real column right by one.
const raw = $('Read Thesis correction').all().map(function (i) {
  const o = i.json;
  return Object.keys(o).filter(function (k) { return k !== 'row_number'; })
                       .map(function (k) { return o[k]; });
});
const inv = $input.all().map(function (i) { return i.json; });
if (inv.length < 100) { throw new Error('ABORT: INVESTORS returned only ' + inv.length + ' rows'); }

// find the label row and derive column positions
let P = null;
for (const r of raw) {
  const idx = r.findIndex(function (c) { return s(c).toLowerCase() === 'sector'; });
  if (idx > 0) {
    P = { firm: 0, contact: 1, email: 2, sector: idx, stage: idx + 1, cheque: idx + 2, geo: idx + 3 };
    break;
  }
}
if (!P) { throw new Error('ABORT: could not locate the Sector label row - Thesis tab layout changed'); }

const byNorm = {};
for (const r of inv) { byNorm[norm(r.investor)] = r; }

const updates = [], flags = [], unmatched = [];
for (const r of raw) {
  const firm = s(r[P.firm]);
  if (!firm || firm.toLowerCase() === 'firm name') { continue; }
  const key = norm(firm);
  const t = byNorm[key] || (ALIAS[key] ? byNorm[norm(ALIAS[key])] : null);
  if (!t) { unmatched.push(firm); continue; }
  if (s(t.do_not_contact).toLowerCase() === 'yes') { continue; }

  const row = { investor: s(t.investor) };
  let changed = 0, thesisChanged = false;
  const pairs = [['contact_person', r[P.contact]], ['email', r[P.email]],
                 ['sector', r[P.sector]], ['stage', r[P.stage]], ['cheque_inr_cr', r[P.cheque]]];
  for (const p of pairs) {
    const k = p[0], v = s(p[1]);
    if (skip(v)) { continue; }
    if (s(t[k]) === v) { continue; }
    row[k] = v; changed++;
    if (k === 'sector' || k === 'stage' || k === 'cheque_inr_cr') { thesisChanged = true; }
  }
  if (changed > 0) { updates.push({ json: row }); }

  // A changed thesis invalidates that investor's existing matches. This job only edits the
  // record - re-matching is judgement work - so raise it in ERROR LOG instead of leaving it silent.
  if (thesisChanged) {
    flags.push({ json: {
      timestamp: new Date().toISOString().slice(0, 10),
      workflow: 'THESIS-AUTO',
      deal_id: '', startup: '', investor: s(t.investor),
      error_type: 'THESIS_CHANGED_NEEDS_REMATCH',
      details: 'Thesis fields updated from corrections sheet; existing PIPELINE rows still reflect the old mandate and need re-matching',
      resolved: ''
    }});
  }
}

if (unmatched.length > 0) { throw new Error('ABORT: thesis rows not found in INVESTORS: ' + unmatched.join(', ') + ' - add an alias'); }
if (updates.length > 20) { throw new Error('ABORT: ' + updates.length + ' updates exceeds guard of 20'); }
return updates.concat(flags);
